#!/usr/bin/env bash
# ui_test_first_skill_test.sh - /ui-test-first (UI のテストファースト) の Skill と、「UI テストは、ビルド → テストの流れに含めない」の方針が、
# Skill / 規約 / ひな形の間で、そろっているかを検証する (文字列による構造の確認。Windows 不要)。
export LC_ALL=C
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
S="$ROOT/skills/ui-test-first/SKILL.md"
REFS="$ROOT/skills/ui-test-first/references"
SR="${TMPDIR:-/tmp}/uitf_all_$$.md"; cat "$S" "$REFS/"*.md > "$SR"; trap 'rm -f "$SR"' EXIT   # v2.74.0: SKILL.md を references/ に分けた。内容の確認は、まとめて読む (S = SKILL.md だけ、SR = SKILL.md + references/)
PASS=0; FAIL=0
ok() { if [ "$2" = 1 ]; then PASS=$((PASS+1)); else FAIL=$((FAIL+1)); echo "FAIL: $1"; fi; }

ok "SKILL.md exists with name: ui-test-first, user-invocable only (disable-model-invocation)" "$([ -f "$S" ] && head -n 6 "$S" | grep -q '^name: ui-test-first$' && head -n 6 "$S" | grep -q '^disable-model-invocation: true$' && head -n 6 "$S" | grep -q '^description: ' && echo 1 || echo 0)"
ok "the loop: plan with one approval -> write UI tests first (Red) -> stub View -> implement (Green) -> full run -> report" "$(grep -q '承認を取る' "$SR" && grep -q 'UI テストを、先に書く (Red)' "$SR" && grep -q '最小の View' "$SR" && grep -q '実装して、Green' "$SR" && grep -q '全 UI テスト' "$SR" && echo 1 || echo 0)"
ok "uses --filter and --ui-timeout, runs in the background, reads screenshots, does not weaken assertions" "$(grep -q -- '--filter' "$SR" && grep -q -- '--ui-timeout' "$SR" && grep -q 'run_in_background: true' "$SR" && grep -q 'ui-screenshots' "$SR" && grep -q 'アサーションを、弱めない' "$SR" && echo 1 || echo 0)"
ok "stops after 3 identical failures; names the per-framework identifiers (WinForms Name / WPF AutomationId / MFC numeric ID)" "$(grep -q '3 回続いたら' "$SR" && grep -q 'AutomationProperties.AutomationId' "$SR" && grep -q '数値' "$SR" && echo 1 || echo 0)"
ok "tells the user not to touch the PC when uitest.settings is desktop=visible" "$(grep -q 'マウスとキーボードに触らないでください' "$SR" && echo 1 || echo 0)"

ok "visual check: Preview tests + --preview / --hold, tell the user before showing, Snap for Claude's own check, background tests use --separate" "$(grep -q 'TestCategory("Preview")' "$SR" && grep -q -- '--preview' "$SR" && grep -q 'HoldForViewing' "$SR" && grep -q 'Snap(' "$SR" && grep -q -- '--separate' "$SR" && grep -q '実行の前に、ユーザーに伝える' "$SR" && echo 1 || echo 0)"
ok "design record: checks docs/design/<screen>.md first, optional 2-3 option comparison (text only), saves it after the approval, and ui-design-review points to it" "$(grep -q 'docs/design/<画面>.md' "$SR" && grep -q '2〜3 案' "$SR" && grep -q '選ばなかった案と理由' "$SR" && grep -q '画像や外部のツールは、使わない' "$SR" && grep -q 'docs/design/<画面>.md' "$ROOT/skills/ui-design-review/SKILL.md" && echo 1 || echo 0)"
ok "design record: does not overwrite a decided design (edits changed rows, appends 変更履歴) and never writes it from guesses" "$(grep -q '変わった行だけを直し' "$SR" && grep -q '推測して書かない' "$SR" && echo 1 || echo 0)"
BTLU="$ROOT/skills/build-test-loop/references/ui-tests.md"
ok "build-test-loop (references/ui-tests.md) documents --hold / --preview and PreviewUiTests" "$(grep -q -- '--hold' "$BTLU" && grep -q -- '--preview' "$BTLU" && grep -q 'PreviewUiTests' "$BTLU" && echo 1 || echo 0)"

ok "demo playback: --present documented (needs --filter) in the skill and build-test-loop (references/ui-tests.md)" "$(grep -q -- '--present' "$SR" && grep -q -- '--present' "$BTLU" && grep -q '赤い枠' "$SR" && echo 1 || echo 0)"
# build-test-loop の SKILL.md から、UI テストの詳細を references/ui-tests.md に分離 (v2.40.0)
BTLS="$ROOT/skills/build-test-loop/SKILL.md"
ok "build-test-loop: SKILL.md keeps a short UI-test entry (not part of build -> test; only when asked or in /ui-test-first; uitest_once.sh; read references/ui-tests.md first) and the details moved out" "$(grep -q '^## UI テスト (FlaUI): ビルド → テストの流れとは、別に、指定されたときだけ実行する' "$BTLS" && grep -q '自動では、続けて実行しない' "$BTLS" && grep -q '求められていなければ、実行しない' "$BTLS" && grep -q '先に `references/ui-tests.md` を読む' "$BTLS" && ! grep -q '^### ' "$BTLS" && [ -f "$BTLU" ] && grep -q 'UiDialogs' "$BTLU" && grep -q '^## 失敗したら' "$BTLU" && grep -q '^## いつ実行するか' "$BTLU" && echo 1 || echo 0)"
ok "build-test-loop: SKILL.md stays small (<= 32000 bytes; was 53294 before the split)" "$([ "$(wc -c < "$BTLS" | tr -d ' ')" -le 32000 ] && echo 1 || echo 0)"
ok "every skill / rule that pointed to the UI-test section now points to references/ui-tests.md (no old wording)" "$(! grep -rIq '`build-test-loop` の「UI テスト」' "$ROOT/skills" "$ROOT/rules" && grep -q 'references/ui-tests.md' "$ROOT/skills/ui-test-first/SKILL.md" && echo 1 || echo 0)"
CSF2="${TMPDIR:-/tmp}/btl_$$"; bash "$ROOT/install/install.sh" --skills-only --skills-dir "$CSF2" >/dev/null 2>&1
ok "install.sh --skills-only copies build-test-loop/references/ui-tests.md (identical to the repo)" "$([ -f "$CSF2/build-test-loop/references/ui-tests.md" ] && cmp -s "$CSF2/build-test-loop/references/ui-tests.md" "$BTLU" && echo 1 || echo 0)"
rm -rf "$CSF2" 2>/dev/null

# 方針: UI テストは、ビルド → テストの流れに、含めない (ユーザーが求めたときと /ui-test-first だけ)
for f in skills/cpp-test-first/SKILL.md skills/csharp-test-first/SKILL.md skills/build-test-loop/SKILL.md skills/new-solution/SKILL.md rules/winforms-csharp.md; do
    ok "$f: UI tests are not run automatically after PASSED; points to /ui-test-first" "$(grep -q 'ui-test-first' "$ROOT/$f" && ! grep -q '続けて `uitest_once.sh`' "$ROOT/$f" && ! grep -q 'Green になってから 1 回' "$ROOT/$f" && echo 1 || echo 0)"
done
ok "build-test-loop: documents --filter / --ui-timeout and that UI tests are not part of build -> test" "$(grep -q -- '--filter' "$ROOT/skills/build-test-loop/SKILL.md" && grep -q -- '--ui-timeout' "$ROOT/skills/build-test-loop/SKILL.md" && grep -q 'ビルド → テスト (`build_test_once.sh`) の流れに、含めない' "$ROOT/skills/build-test-loop/SKILL.md" && echo 1 || echo 0)"

# new-solution: 了承の質問の選択肢に、UI テストを足さない (v2.63.2)
ok "new-solution: the approval question has no UI-test option when ui-tests is none" "$(grep -q '了承の質問の選択肢に、UI テストを足さない' "$ROOT/skills/new-solution/SKILL.md" && echo 1 || echo 0)"

# new-solution: --ui-tests は、質問しない。指定がなければ、どの種類でも none。flaui と明示されたときだけ作る (v2.63.0)
NS="$ROOT/skills/new-solution/SKILL.md"
ok "new-solution: never asks about --ui-tests; defaults to none for every type; builds flaui only when explicit" "$(grep -q '`--ui-tests`: \*\*質問しない。' "$NS" && grep -q 'どの種類でも、既定の `none`' "$NS" && grep -q '`flaui` と明示されたときだけ、作る' "$NS" && ! grep -q '種類によって、質問を省かない' "$NS" && echo 1 || echo 0)"

ok "dialogs / sub-windows (v2.69.0): the plan adds 種類 / 開き方 / 閉じ方と結果 / 開くときの前提 for non-main screens, the opener button is a part in the main View, dialog parts are found with Find(window, \"Id\"), the design record has the opener section" "$(grep -q '画面の種類 (メインウィンドウか、ダイアログ・サブウィンドウか)' "$SR" && grep -q '開き方' "$SR" && grep -q '閉じ方と結果' "$SR" && grep -q '開くときの前提' "$SR" && grep -q '開くボタンも、部品として' "$SR" && grep -q 'Find(dlg, \"OkButton\")' "$SR" && grep -q '## 開き方と閉じ方 (メインウィンドウ以外のときだけ)' "$SR" && grep -q 'モーダルなダイアログ | モードレスなウィンドウ' "$SR" && echo 1 || echo 0)"
ok "dialogs (v2.69.0): build-test-loop's UI test reference tells to use Find(window, \"Id\") inside dialogs" "$(grep -q 'Find(window, \"Id\")' "$ROOT/skills/build-test-loop/references/ui-tests.md" && echo 1 || echo 0)"
ok "Model switch + integration (v2.70.0): APP_MODEL fake/real, switched at the composition root, not read in Release, UITEST_MODEL > uitest.settings model= > fake, Fake lives in the app/data layer, integration = same UI tests with model=real after the real Model's unit tests PASSED, Fake kept, contract tests align Fake and the real Model" "$(grep -q '## Model の差し替え (Fake ↔ 本物)' "$SR" && grep -q '## 結合 (Fake → 本物)' "$SR" && grep -q 'APP_MODEL' "$SR" && grep -q 'UITEST_MODEL' "$SR" && grep -q 'model=real' "$SR" && grep -q 'Release のビルドでは、`APP_MODEL` を読まない' "$SR" && grep -q 'InMemory<名前>Repository' "$SR" && grep -q 'Fake と本物は、契約テスト (同じテストを、両方に通す) で、合わせる' "$SR" && grep -q '契約テスト (Fake と本物の両方) が `PASSED`' "$SR" && grep -q '契約テスト (クラス名)' "$SR" && grep -q 'Fake を、捨てない' "$SR" && grep -q '依存する Model' "$SR" && grep -q '## 依存する Model (Fake を使うときだけ)' "$SR" && echo 1 || echo 0)"
ok "Model switch (v2.70.0): build-test-loop's UI test reference mentions APP_MODEL" "$(grep -q 'APP_MODEL' "$ROOT/skills/build-test-loop/references/ui-tests.md" && echo 1 || echo 0)"
ok "contract tests (v2.71.0): CONTRACT-TESTS.md for C# (abstract base + one concrete class per implementation, Create(), real class added Red -> Green, no Ignore/Inconclusive, dev connection only) and C++ (TYPED_TEST / TEST_P, no GTEST_SKIP), linked from PROJECT-LAYOUT.md / DLL-LAYOUT.md" "$(C="$ROOT/skills/csharp-test-first/CONTRACT-TESTS.md"; P="$ROOT/skills/cpp-test-first/CONTRACT-TESTS.md"; [ -f "$C" ] && [ -f "$P" ] && grep -q 'public abstract class OrderRepositoryContractTests' "$C" && grep -q 'protected abstract IOrderRepository Create()' "$C" && grep -q 'InMemoryOrderRepositoryContractTests : OrderRepositoryContractTests' "$C" && grep -q '本物の具体クラス' "$C" && grep -q 'Assert.Inconclusive' "$C" && grep -q '本番の接続先で、実行しない' "$C" && grep -q 'test_guard.py' "$C" && grep -q 'TYPED_TEST_SUITE' "$P" && grep -q 'INSTANTIATE_TEST_SUITE_P' "$P" && grep -q 'GTEST_SKIP' "$P" && grep -q 'CONTRACT-TESTS.md' "$ROOT/skills/csharp-test-first/PROJECT-LAYOUT.md" && grep -q 'CONTRACT-TESTS.md' "$ROOT/skills/cpp-test-first/DLL-LAYOUT.md" && echo 1 || echo 0)"
ok "contract tests (v2.71.0): test_guard really flags what the docs forbid (Ignore / Inconclusive / GTEST_SKIP / DISABLED_ -> TMG002)" "$(grep -q 'TMG002 error   \[Ignore\] / Assert.Inconclusive / GTEST_SKIP / DISABLED_' "$ROOT/skills/build-test-loop/scripts/test_guard.py" && echo 1 || echo 0)"
ok "desktop speed (v2.73.0): the reference lists the measured fixed cost of --separate for WPF and when to use --visible; the SKILL points to it" "$(grep -q 'WPF は、別のデスクトップ (`--separate`) だと、1 件あたり、固定費がかかる' "$ROOT/skills/build-test-loop/references/ui-tests.md" && grep -q 'exit: killed after N ms' "$ROOT/skills/build-test-loop/references/ui-tests.md" && grep -q '1 件 約 5〜10 秒遅い' "$SR" && echo 1 || echo 0)"
ok "SKILL.md split (v2.74.0): SKILL.md stays small (<= 24000 bytes; was 31978 before the split) and points to the four references, each with the cue to read it first" "$([ "$(wc -c < "$S" | tr -d ' ')" -le 24000 ] && for f in design-record dialogs model-switching preview; do [ -f "$REFS/$f.md" ] || exit 1; grep -q "references/$f.md" "$S" || exit 1; done; grep -q '先に `references/dialogs.md` を読み' "$S" && grep -q '先に `references/model-switching.md` を読み' "$S" && grep -q '書式と書き方は `references/design-record.md`' "$S" && grep -q '手順・オプション・注意は、\*\*`references/preview.md`' "$S" && echo 1 || echo 0)"
ok "SKILL.md split (v2.74.0): each reference says when to read it, and nothing from the old SKILL.md was dropped (the detailed sections live in the references)" "$(for f in design-record dialogs model-switching preview; do head -n 4 "$REFS/$f.md" | grep -q 'ui-test-first' || exit 1; done; grep -q '^## Model の差し替え (Fake ↔ 本物)' "$REFS/model-switching.md" && grep -q '^## 結合 (Fake → 本物)' "$REFS/model-switching.md" && grep -q '^## 目視確認: UI テストは裏で' "$REFS/preview.md" && grep -q '^### デモとして再生する' "$REFS/preview.md" && grep -q '^# <画面名> の設計' "$REFS/design-record.md" && grep -q 'Find(window, "Id")' "$REFS/dialogs.md" && echo 1 || echo 0)"
ok "ui-test-first (v2.77.0): tells to use UiDialogs.SetText and UiDialogs.CloseWindow, not .Text = / Window.Close() (slow in a separate desktop)" "$(grep -q -F 'UiDialogs.SetText(要素' "$S" && grep -q -F 'UiDialogs.CloseWindow(dlg)' "$S" && grep -q -F 'UiDialogs.CloseWindow(dlg)' "$REFS/dialogs.md" && grep -q -F 'UiDialogs.SetText(Find(dlg' "$REFS/dialogs.md" && echo 1 || echo 0)"
ok "ui-test-first (v2.78.0): Model means a repository only; a dialog's data classes are not Model (logic layer by default, View layer only if tightly bound, never the data layer)" "$(grep -q -F '## 「Model」とは何か、画面のデータは、どこに置くか' "$REFS/model-switching.md" && grep -q -F 'ダイアログ・画面が使う、データのクラス' "$REFS/model-switching.md" && grep -q -F 'ダイアログ・画面のデータのクラスは、Model ではない' "$S" && grep -q -F 'ダイアログ・画面が使うデータのクラス' "$ROOT/rules/winforms-csharp.md" && grep -q -F 'ダイアログ・画面が使うデータのクラス' "$ROOT/rules/wpf-csharp.md" && grep -q -F 'ダイアログ・画面が使うデータの構造体・クラス' "$ROOT/skills/cpp-test-first/DLL-LAYOUT.md" && echo 1 || echo 0)"
ok "ui-test-first (v2.79.0): the plan must include an integration step when the Model is not real yet (contract tests, model=real, status only after integration, restore model=fake)" "$(grep -q -F '結合の手順 (依存する Model が、本物でないときは、必ず、1 行入れる)' "$S" && grep -q -F '結合するまで「Fake あり / 本物あり」とし' "$S" && echo 1 || echo 0)"
ok "ui-test-first (v2.81.0): a dialog's data class may hold pure rules (IsValid), no extra Presenter/ViewModel per dialog; WinForms same layer / MFC constructor argument + DoDataExchange" "$(grep -q -F '## ダイアログのデータと規則の置き場所 (計画に 1 行足す)' "$REFS/dialogs.md" && grep -q -F 'ダイアログ専用の Presenter / ViewModel は、増やさない' "$REFS/dialogs.md" && grep -q -F 'ダイアログ専用の Presenter / ViewModel は、増やさない' "$ROOT/rules/winforms-csharp.md" && grep -q -F 'Presenter の内側に入れ子にせず' "$ROOT/rules/winforms-csharp.md" && grep -q -F 'ViewModel の内側に入れ子にせず' "$ROOT/rules/wpf-csharp.md" && grep -q -F 'コンストラクターの引数 (参照またはポインタ) で、このデータのクラスを受け取り' "$ROOT/skills/cpp-test-first/DLL-LAYOUT.md" && grep -q -F '`CDialog` 派生クラスには、業務の規則を書かない' "$ROOT/skills/cpp-test-first/DLL-LAYOUT.md" && echo 1 || echo 0)"
ok "dialogs (v2.82.0): a dialog does not change the data it was given until OK (validate on temporary data, write back on OK) in rules, DLL-LAYOUT and dialogs.md" "$(for f in "$ROOT/rules/winforms-csharp.md" "$ROOT/rules/wpf-csharp.md" "$ROOT/skills/cpp-test-first/DLL-LAYOUT.md" "$REFS/dialogs.md"; do grep -q -F 'ダイアログは、確定 (OK) するまで、渡されたデータを変更しない' "$f" || { echo 0; exit; }; done; echo 1)"
ok "dialogs (v2.83.0): modal = no change until OK; modeless = live shared data with change notification, single instance, WaitWindow in the UI test" "$(for f in "$ROOT/rules/winforms-csharp.md" "$ROOT/rules/wpf-csharp.md" "$ROOT/skills/cpp-test-first/DLL-LAYOUT.md" "$REFS/dialogs.md"; do grep -q -F 'モーダルなダイアログは、確定 (OK) するまで、渡されたデータを変更しない' "$f" && grep -q -F 'モードレスなウィンドウは、OK がないので、持っているデータ' "$f" || { echo 0; exit; }; done; grep -q -F '## モードレスなサブウィンドウ (OK がない)' "$REFS/dialogs.md" && grep -q -F '`WaitWindow(title)`' "$REFS/dialogs.md" && grep -q -F '単一インスタンス' "$REFS/dialogs.md" && echo 1 || echo 0)"
ok "dialogs (v2.84.0): MFC modeless pitfalls (OnOK does nothing, OnCancel = DestroyWindow, PostNcDestroy unregisters/nullptr/delete this, SetForegroundWindow) in DLL-LAYOUT.md and dialogs.md, with the Enter and reopen UI tests" "$(for f in "$ROOT/skills/cpp-test-first/DLL-LAYOUT.md" "$REFS/dialogs.md"; do grep -q -F '`OnOK` は何もしない' "$f" && grep -q -F '`PostNcDestroy` で' "$f" && grep -q -F 'SetForegroundWindow' "$f" || { echo 0; exit; }; done; grep -q -F '入力欄で Enter を押しても、閉じない' "$REFS/dialogs.md" && grep -q -F '閉じたあとに『編集』を押すと、新しく開く' "$REFS/dialogs.md" && echo 1 || echo 0)"
ok "ui-test-first (v2.85.0): image/sketch input: sketch.md (read the image, show the reading, confirm what the image cannot decide, save to docs/design/images/, compare only on request), SKILL.md points to it" "$(grep -q -F '画像 (手書きのスケッチ、ドローツールの図、画面の写真) が渡されたか' "$S" && grep -q -F 'references/sketch.md' "$S" && grep -q -F 'docs/design/images/' "$REFS/sketch.md" && grep -q -F 'ユーザーが頼んだときだけ' "$REFS/sketch.md" && grep -q -F '確信' "$REFS/sketch.md" && grep -q -F 'スケッチ: docs/design/images/' "$REFS/design-record.md" && echo 1 || echo 0)"
# 配布: install.sh が、skills/* をコピーする (新しい Skill も、対象)
out="$(bash "$ROOT/install/install.sh" --skills-only --dry-run --skills-dir "${TMPDIR:-/tmp}/uitf_skills_$$" 2>&1)"
ok "install.sh --dry-run lists skills/ui-test-first/SKILL.md" "$(echo "$out" | grep -q 'ui-test-first' && echo 1 || echo 0)"

echo "PASS=$PASS FAIL=$FAIL"
[ "$FAIL" = 0 ]
